#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
gen_map_anchors.py —— 从 TMJ 几何自动生成「驻守锚点」与「观察方向」

每个区域取所有矩形对象的包围盒中心；按阵营（T/CT）把锚点朝"敌方出生点方向"
偏移 15%（不超出包围盒），并生成朝向敌方的角度。

写回 assets/config/tactics/<map>.ini 的生成块（保留手工内容）：
    # --- generated by gen_map_anchors.py (do not edit) ---
    [anchor.T.<area>]
    x=..
    y=..
    ...
"""
import json
import math
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
TACTICS = os.path.join(ROOT, "assets", "config", "tactics")
MARK = "# --- generated by gen_map_anchors.py"


def load_tmj(map_id):
    p = os.path.join(ROOT, "assets", "cs2d", "maps", map_id + ".tmj")
    with open(p, encoding="utf-8") as f:
        return json.load(f)


def obj_bbox(objs):
    xs, ys, xe, ye = [], [], [], []
    for o in objs:
        x, y = o.get("x", 0), o.get("y", 0)
        w, h = o.get("width", 0), o.get("height", 0)
        xs.append(x); ys.append(y); xe.append(x + w); ye.append(y + h)
    if not xs:
        return None
    return min(xs), min(ys), max(xe), max(ye)


def centroid(objs):
    n = len(objs) or 1
    return (sum(o.get("x", 0) + o.get("width", 0) / 2 for o in objs) / n,
            sum(o.get("y", 0) + o.get("height", 0) / 2 for o in objs) / n)


def collect(layers):
    areas, spawns = {}, {}
    for layer in layers:
        name = layer.get("name", "")
        if layer.get("type") == "group":
            for sub in layer.get("layers", []):
                bb = obj_bbox(sub.get("objects", []))
                if bb:
                    areas[sub["name"]] = bb
        elif layer.get("type") == "objectgroup":
            objs = layer.get("objects", [])
            if not objs:
                continue
            if "spawn_t" in name:
                spawns["T"] = centroid(objs)
            elif "spawn_ct" in name:
                spawns["CT"] = centroid(objs)
    return areas, spawns


def main():
    maps = sys.argv[1:] or ["dust_2", "mirage", "ancient_ruins"]
    for m in maps:
        data = load_tmj(m)
        areas, spawns = collect(data["layers"])
        if not spawns or not areas:
            print(f"[skip] {m}: spawn/areas missing")
            continue
        lines = [MARK]
        for area, (x0, y0, x1, y1) in sorted(areas.items()):
            cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
            span = max(1.0, math.hypot(x1 - x0, y1 - y0) * 0.15)
            for team, (ex, ey) in spawns.items():
                dx, dy = ex - cx, ey - cy
                d = max(1.0, math.hypot(dx, dy))
                ax = min(x1 - 4, max(x0 + 4, cx + dx / d * span))
                ay = min(y1 - 4, max(y0 + 4, cy + dy / d * span))
                ang = math.degrees(math.atan2(ey - cy, ex - cx))
                lines.append(f"[anchor.{team}.{area}]")
                lines.append(f"x={ax:.1f}")
                lines.append(f"y={ay:.1f}")
                lines.append(f"[look.{team}.{area}]")
                lines.append(f"0={ang:.1f}")
        path = os.path.join(TACTICS, m + ".ini")
        old = ""
        if os.path.exists(path):
            old = open(path, encoding="utf-8").read()
            cut = old.find(MARK)
            if cut >= 0:
                old = old[:cut].rstrip() + "\n\n"
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(old + "\n".join(lines) + "\n")
        print(f"[ok] {m}: {len(areas)} areas, {len(spawns)} spawns → {path}")


if __name__ == "__main__":
    sys.exit(main())
